A2-local-directive.main:
import { Component, Directive, computed, input, provideZonelessChangeDetection } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';

@Directive({ selector: '[appBar]', host: { role: 'progressbar', '[attr.aria-valuenow]': 'value()', '[attr.data-state]': 'state()' } })
class Bar {
  readonly value = input<number | null>(null);
  readonly state = computed(() => (this.value() === null ? 'indeterminate' : 'loading'));
}

@Component({ selector: 'app-root', imports: [Bar], template: '<div appBar [value]="40"></div>' })
class App {}

bootstrapApplication(App, { providers: [provideZonelessChangeDetection()] });

