@Component({ selector: 'app-root', template: '<p>{{ side }}</p>' })
class App {
  readonly side = String(
    calculateArrowGeometry({ left: 0, top: 0, width: 10, height: 10 }, { left: 0, top: 10, width: 100, height: 40 }, 'bottom', { size: 8, padding: 2 }).available,
  );
}

bootstrapApplication(App, { providers: [provideZonelessChangeDetection()] });

