D-dialog-flow.main:
import { Component, TemplateRef, ViewContainerRef, inject, provideZonelessChangeDetection, viewChild } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';
import { OverlayTriggerDirective } from '@quartz-headless/core';
import { DialogService } from '@quartz-headless/primitives';

@Component({
  selector: 'app-root',
  imports: [OverlayTriggerDirective],
  template: '<button (click)="open()">Open</button><button qzOverlayTrigger [overlayTemplate]="panel">Pop</button><ng-template #panel><div>Panel</div></ng-template><ng-template #tpl let-ref><button (click)="ref.close()">Close</button></ng-template>',
})
class App {
  private readonly dialogs = inject(DialogService);
  private readonly vcr = inject(ViewContainerRef);
  readonly tpl = viewChild.required<TemplateRef<unknown>>('tpl');
  open() { this.dialogs.open(this.tpl(), this.vcr); }
}

bootstrapApplication(App, { providers: [provideZonelessChangeDetection()] });
